using System.Text;

namespace Erp.CodeGen.Emit;

/// <summary>
/// Collects generated files and writes them. Files are written with LF endings and UTF-8 without BOM, so output is
/// byte-identical on every machine. Generated files that are no longer produced are deleted from the owned folders;
/// a file is only ever deleted if it carries the &lt;auto-generated&gt; marker.
/// </summary>
public sealed class OutputSet
{
    public const string Marker = "<auto-generated>";

    private static readonly UTF8Encoding Utf8NoBom = new(encoderShouldEmitUTF8Identifier: false);

    private readonly SortedDictionary<string, string> _files = new(StringComparer.Ordinal);
    private readonly SortedSet<string> _ownedFolders = new(StringComparer.Ordinal);

    public IReadOnlyDictionary<string, string> Files => _files;

    public void Own(string relativeFolder) => _ownedFolders.Add(relativeFolder.Replace('\\', '/'));

    public void Add(string relativePath, string content)
    {
        var path = relativePath.Replace('\\', '/');
        if (!content.Contains(Marker, StringComparison.Ordinal))
        {
            throw new InvalidOperationException($"{path} lacks the {Marker} marker");
        }

        if (!_files.TryAdd(path, content.Replace("\r\n", "\n", StringComparison.Ordinal)))
        {
            throw new InvalidOperationException($"{path} is generated twice");
        }

        Own(Path.GetDirectoryName(path)!.Replace('\\', '/'));
    }

    /// <summary>Writes every file under <paramref name="root"/> and removes stale generated files. Returns counts.</summary>
    public (int Written, int Unchanged, int Deleted) WriteTo(string root)
    {
        int written = 0, unchanged = 0, deleted = 0;
        foreach (var (relative, content) in _files)
        {
            var path = Path.Combine(root, relative);
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            var bytes = Utf8NoBom.GetBytes(content);
            if (File.Exists(path) && File.ReadAllBytes(path).AsSpan().SequenceEqual(bytes))
            {
                unchanged++;
                continue;
            }

            File.WriteAllBytes(path, bytes);
            written++;
        }

        foreach (var folder in _ownedFolders)
        {
            var directory = Path.Combine(root, folder);
            if (!Directory.Exists(directory))
            {
                continue;
            }

            foreach (var file in Directory.GetFiles(directory))
            {
                var relative = Path.GetRelativePath(root, file).Replace('\\', '/');
                if (!_files.ContainsKey(relative) && File.ReadAllText(file).Contains(Marker, StringComparison.Ordinal))
                {
                    File.Delete(file);
                    deleted++;
                }
            }
        }

        return (written, unchanged, deleted);
    }
}
